  align-items: center !important;
  justify-content: center !important;
  margin: 8px auto !important;
  padding: 4px 14px !important;
  background: var(--system-msg-bg) !important;
  border: 1px solid var(--chat-header-border) !important;
  border-radius: 999px !important;
  color: var(--system-msg-color) !important;
  font-size: 11px !important;
  font-weight: 400 !important;
  letter-spacing: 0.3px !important;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.1) !important;
}

.nuo-pat-msg::after,
.nuo-pat-msg::before {
  content: none !important;
}

/* ============================================================
   12. 撤回消息（吸附紧凑）
   ============================================================ */

.msg-bubble-wrapper:has([class*="recall"]),
.msg-bubble-wrapper:has(.msg-revoke),
.message-wrapper:has([class*="recall"]) {
  margin-top: -10px !important;
  margin-bottom: -4px !important;
  padding-top: 0 !important;
  padding-bottom: 0 !important;
}

.msg-system,
[class*="msg-recall"],
[class*="system-msg"],
.msg-revoke {
  font-size: 0 !important;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  margin: -5px auto 4px !important;
  padding: 2px 12px !important;
  background: var(--system-msg-bg) !important;
  border: 1px solid var(--chat-header-border) !important;
  border-radius: 999px !important;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.1) !important;
  white-space: nowrap !important;
}

.msg-system::before,
[class*="msg-recall"]::before,
[class*="system-msg"]::before,
.msg-revoke::before {
  content: "叮咚 您有一條新的訊息通知被撤回已阻止៷>ᴗ<៷" !important;
  font-size: 11px !important;
  color: var(--system-msg-color) !important;
  opacity: 0.75 !important;
  font-weight: 400 !important;
  letter-spacing: 0.3px !important;
  display: inline-block !important;
}

.msg-system a,
.msg-system button,
[class*="msg-recall"] a,
[class*="msg-recall"] button,
[class*="reedit"] {
  font-size: 11px !important;
  color: #3b82f6 !important;
  text-decoration: none !important;
  margin-left: 6px !important;
  font-weight: 500 !important;
  cursor: pointer !important;
}

/* ============================================================
   13. 通话卡片与心声安全间距修复
   ============================================================ */

[class*="call"],
[class*="voip"],
.msg-call-card,
.msg-bubble-wrapper:has([class*="call"]),
.msg-bubble-wrapper:has([class*="voip"]) {
  margin-top: 8px !important;
  margin-bottom: 8px !important;
