  gap: 6px !important;
}
.voice-msg .voice-waveform {
  flex: 0 0 auto !important;
  width: auto !important;
  min-width: 0 !important;
  gap: 2px !important;
}
.voice-msg .voice-waveform-bar { width: 2px !important; }
.voice-msg .voice-duration {
  min-width: 0 !important;
  text-align: left !important;
}

/* 语音条:再短 */
.voice-msg .voice-controls-row {
  gap: 4px !important;
  padding: 4px 10px !important;
}
.voice-msg .voice-play-btn {
  width: 18px !important;
  height: 18px !important;
}
.voice-msg .voice-play-btn svg {
  width: 15px !important;
  height: 15px !important;
}
.voice-msg .voice-waveform {
  gap: 1px !important;
  height: 20px !important;
}
.voice-msg .voice-waveform-bar {
  width: 1.5px !important;
}
.voice-msg .voice-duration {
  font-size: 10px !important;
}

