/* 原提示词藏起来 */
.chat-detail-screen .input-box-custom::placeholder{color:transparent!important;opacity:0!important}

/* 新提示词：只在输入框为空时显示，不挡点击 */
.chat-detail-screen .input-action-bar-custom{position:relative}
.chat-detail-screen .input-action-bar-custom:has(.input-box-custom:placeholder-shown)::before{content:var(--oo-ph-text);position:absolute;left:var(--oo-ph-left);top:50%;transform:translateY(-50%);font-size:15px;font-weight:400;line-height:1;color:var(--oo-ph);pointer-events:none;white-space:nowrap}

/* ===== 聊天背景（日夜跟随）===== */
.chat-detail-screen{
  --oo-bg:#ffffff;
  --chat-bg-color:#ffffff;
  --chat-bg-image:none;
  --chat-bg-overlay:rgba(0,0,0,0);
  --chat-bg-blur:0px;
}
