  .chat-detail-screen{--oo-bg:#000000;--chat-bg-color:#000000}
}

.chat-detail-screen,
.chat-detail-screen .chat-messages-area{background:var(--oo-bg)!important;background-image:none!important}
.chat-detail-screen .chat-message-list-custom{background:transparent!important}

/* 居中时间戳：「信息 · 短信」在上，时间在下 */
.chat-detail-screen .timestamp-custom{text-align:center}
.chat-detail-screen .timestamp-custom::before{content:"信息 · 短信";display:block;font-weight:600;color:inherit;margin-bottom:2px}

/* === 转账卡片 === */

[data-theme-style="qq"] .msg-transfer-card {
