/* == 翻译 == */
:root {
  /* 0 = 随系统/点击触发；1 = 永远显示 */
  --translation-always-show: 1;
  /* 官方规范：从根源隐藏自带的「查看翻译」按钮 */
  --translation-btn-display: none;

  --tr-overlap: -9px;             /* 翻译压进气泡的距离 */
  --tr-indent: 14px;              /* 翻译文字离气泡左边的距离 */
  --tr-size: 12px;                /* 翻译字号 */

  /* 黑色描边：36 个方向的高精度平滑阴影 */
  --tr-outline:
    0.115em 0.000em 0 #000, 0.111em 0.030em 0 #000, 0.100em 0.057em 0 #000, 0.081em 0.081em 0 #000,
    0.058em 0.100em 0 #000, 0.030em 0.111em 0 #000, 0.000em 0.115em 0 #000, -0.030em 0.111em 0 #000,
    -0.057em 0.100em 0 #000, -0.081em 0.081em 0 #000, -0.100em 0.057em 0 #000, -0.111em 0.030em 0 #000,
    -0.115em 0.000em 0 #000, -0.111em -0.030em 0 #000, -0.100em -0.057em 0 #000, -0.081em -0.081em 0 #000,
    -0.058em -0.100em 0 #000, -0.030em -0.111em 0 #000, 0.000em -0.115em 0 #000, 0.030em -0.111em 0 #000,
    0.058em -0.100em 0 #000, 0.081em -0.081em 0 #000, 0.100em -0.058em 0 #000, 0.111em -0.030em 0 #000,
    0.059em 0.008em 0 #000, 0.048em 0.036em 0 #000, 0.023em 0.055em 0 #000, -0.008em 0.059em 0 #000,
    -0.036em 0.048em 0 #000, -0.055em 0.023em 0 #000, -0.059em -0.008em 0 #000, -0.048em -0.036em 0 #000,
    -0.023em -0.055em 0 #000, 0.008em -0.059em 0 #000, 0.036em -0.048em 0 #000, 0.055em -0.023em 0 #000;
}

/* 1. 气泡内部彻底清空：不放任何按钮、不垫任何透明层，选字复制完全自由 */
.msg-translation-wrapper {
  display: none !important;
}

/* 2. 气泡外部独立翻译块（白字黑描边，完全悬浮在气泡外下沿） */
.msg-translation-detached {
  display: block !important;
  position: relative !important;
  z-index: 6 !important;                 /* 悬浮层级，绝不穿透影响气泡内部 */
  margin: var(--tr-overlap) 0 0 0 !important;
  width: fit-content !important;
  max-width: 188% !important;
  min-width: 0 !important;
  box-sizing: border-box !important;
  pointer-events: none;                  /* 不拦截任何点击 */
}

.msg-translation-detached-content {
  position: relative !important;
  min-width: 0 !important;
  padding: 0 0 0 var(--tr-indent) !important;
  background: transparent !important;
  border: none !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  color: #fff !important;
  font-size: var(--tr-size) !important;
  font-weight: 800 !important;
  line-height: 1.3 !important;
  letter-spacing: 0.2px;
  text-shadow: var(--tr-outline) !important;
  word-break: break-word !important;
}

.msg-translation-detached-content::before,
.msg-translation-detached-content::after {
  content: none !important;
}

/* ===== 返回键旁未读:去掉红点,只留数字(日夜跟随)===== */
/* 红点:缩成 0 看不见(不要用 display:none,数字可能挂在它里面) */
.chat-detail-screen .nuo-chat-header-unread-dot {
  --chat-header-unread-size: 0;
  --chat-header-unread-bg: transparent;
  --chat-header-unread-border: none;
  --chat-header-unread-shadow: none;
  --chat-header-unread-animation: none;
  overflow: visible !important;
  background: transparent !important; border: none !important;
  box-shadow: none !important; animation: none !important;
}

/* 数字:无底色、无描边,贴在返回键右边垂直居中 */
.chat-detail-screen .nuo-chat-header-unread-num {
  --chat-header-unread-num-display: flex;
  --chat-header-unread-num-bg: transparent;
  --chat-header-unread-num-color: var(--hdr-fg, #111114);   /* 跟顶栏文字色:日间深、夜间白 */
  --chat-header-unread-num-size: 15px;
  --chat-header-unread-num-weight: 500;
  --chat-header-unread-num-min-width: 0;
  --chat-header-unread-num-height: auto;
  --chat-header-unread-num-padding: 0;
  --chat-header-unread-num-radius: 0;
  --chat-header-unread-num-border: none;
  --chat-header-unread-num-shadow: none;
  --chat-header-unread-num-top: 50%;
  --chat-header-unread-num-left: 30px;                       /* 离返回键左边的距离,想靠近/远离箭头改这个 */
  --chat-header-unread-num-transform: translateY(-50%);

  background: transparent !important;
  color: var(--hdr-fg, #111114) !important;
  border: none !important; box-shadow: none !important;
  min-width: 0 !important; height: auto !important;
  padding: 0 !important; border-radius: 0 !important;
  opacity: 1 !important; visibility: visible !important;
}

/* 如果数字是挂在红点里面的:让红点停在返回键右侧正中,数字跟着它 */
.chat-detail-screen .nuo-chat-header-unread-dot:has(.nuo-chat-header-unread-num) {
  --chat-header-unread-top: 50%;
  --chat-header-unread-left: 30px;
  --chat-header-unread-transform: none;
}
.chat-detail-screen .nuo-chat-header-unread-dot .nuo-chat-header-unread-num {
  --chat-header-unread-num-top: 0;
  --chat-header-unread-num-left: 0;
  --chat-header-unread-num-transform: translateY(-50%);
}

